├── public/                       # Static assets
├── types/                        # TypeScript type definitions
└── prismicio.ts                  # Prismic client configuration
```

---

### **2. Prismic Configuration**

**File: `/Users/stjepandzojic/projects/zos-website/prismicio.ts`**
```typescript
const routes: Route[] = [
  { type: 'info', path: '/informacije/:uid' },
  { type: 'news', path: '/vijesti/:uid' },
  { type: 'stories', path: '/price-osjeckih-sportasa/:uid' },
  { type: 'event', path: '/dogadaji' },
  { type: 'club', path: '/clanice' },
];

export const createClient = (config: ClientConfig = {}) => {
  const client = baseCreateClient(repositoryName, {
    routes,
    fetchOptions: { cache: 'no-store' },
    ...config,
  });
  enableAutoPreviews({ client });
  return client;
};
```

**Key Files:**
- `/Users/stjepandzojic/projects/zos-website/prismicio.ts` - Client setup and route definitions
- `/Users/stjepandzojic/projects/zos-website/prismicio-types.d.ts` - Auto-generated TypeScript types (48K file)
- `/Users/stjepandzojic/projects/zos-website/slicemachine.config.json` - Slice Machine configuration

---

### **3. "Vijesti" (News) Section - Complete End-to-End Pattern**

#### **A. Prismic Custom Type Definition**
**File: `/Users/stjepandzojic/projects/zos-website/customtypes/news/index.json`**

The News document type includes:
- **Main Tab:**
  - `uid` - Document identifier
  - `title` - News title
  - `description` - Short description shown on card
  - `date` - Publication date (optional, can be future-dated)
  - `hero_image` - Featured image (1600x720 recommended)
  - `opening_text` - Introductory text
  - `content` - Rich text content with formatting, images, embeds
  - `related_articles` - Link group to other news/events
  - `sports` - Multi-select group for sport categories
  - `gallery` - Image group (4 images max) with cropped (360x232) and normal versions
  - `slices` - For slice zone (currently empty choices)
- **SEO & Metadata Tab:**
  - `meta_title`, `meta_description`, `meta_image` (2400x1260)

#### **B. Page Structure**

**List Page: `/Users/stjepandzojic/projects/zos-website/app/vijesti/page.tsx`**
```typescript
export default async function Page({
  searchParams,
}: {
  searchParams: Promise<{ kategorija?: string }>;
}) {
  const { kategorija } = await searchParams;
  return (
    <>
      <Title>Vijesti</Title>
      <MainNews />
      <Archive initialFilter={kategorija} />
    </>
  );
}
```

**Single Page: `/Users/stjepandzojic/projects/zos-website/app/vijesti/[uid]/page.tsx`**
```typescript
export async function generateMetadata({
  params,
}: {
  params: Promise<{ uid: string }>;
}): Promise<Metadata> {
  const { uid } = await params;
  const news = await getSingleNews(uid);
  return await generateSeoData({...});
}

export default async function Page({
  params,
}: {
  params: Promise<{ uid: string }>;
}) {
  const { uid } = await params;
  const news = await getSingleNews(uid);
  return <SingleNews news={news} />;
}
```

#### **C. Utility Functions**

**Get Single Article: `/Users/stjepandzojic/projects/zos-website/app/vijesti/utils/getSingleNews.ts`**
```typescript
export const getSingleNews = async (uid: string) => {
  try {
    const client = createClient();
    const news = await client.getByUID('news', uid);
    return news;
  } catch {
    notFound();
  }
};
```

**Get List: `/Users/stjepandzojic/projects/zos-website/app/_shared/utils/getNews.ts`**
```typescript
export async function getNews({ filter, limit = 9, page = 1 }: Props) {
  try {
    let news: Query<NewsDocument<string>>;
    const client = createClient();

    if (filter === 'news' || !filter) {
      news = await client.getByType('news', {
        orderings: { field: 'my.news.date', direction: 'desc' },
        pageSize: limit,
        page,
      });
    } else if (filter === 'combat-sports') {
      news = await client.getByType('news', {
        filters: [prismicFilter.any('my.news.sports.sport', [...])],
        pageSize: limit,
        page,
      });
    } else {
      news = await client.getByType('news', {
        filters: [prismicFilter.at('my.news.sports.sport', ...)],
        pageSize: limit,
        page,
      });
    }
    return { news: news.results, totalPages: news.total_pages || 1 };
  } catch {
    return { news: [], totalPages: 1 };
  }
}
```

**Configuration (SEO): `/Users/stjepandzojic/projects/zos-website/app/(index)/utils/getNewsConfiguration.ts`**
```typescript
export const getNewsConfiguration = async () => {
  try {
    const client = createClient();
    const data = await client.getSingle('news_configuration');
    return data;
  } catch {
    return null;
  }
};
```

#### **D. Components**

**NewsArticle Card: `/Users/stjepandzojic/projects/zos-website/app/_shared/NewsArticle.tsx`**
- Reusable card component with hover effects
- Shows: sport badge, title, description (if main), date
- Accepts `isMain` prop for styling differences
- Links to `/vijesti/{uid}`

**MainNews: `/Users/stjepandzojic/projects/zos-website/app/vijesti/_fragments/MainNews.tsx`**
- Client component
- Displays 9 news items in grid layout: 1 main + 4 secondary + 4 in row
- Uses `getNews()` utility
- Shows skeleton loading states

**Archive: `/Users/stjepandzojic/projects/zos-website/app/vijesti/_fragments/Archive.tsx`**
- Client component with filtering and search
- Uses `NEWS_FILTERS` constant
- Pagination logic with ellipsis
- Supports initial filter via URL params

**SingleNews: `/Users/stjepandzojic/projects/zos-website/app/vijesti/_fragments/SingleNews.tsx`**
- Displays full article with rich text content
- Social sharing buttons (Facebook, LinkedIn, Twitter, Email)
- Gallery display
- Related articles/recommendations (up to 3)
- Fetches related articles and auto-loads news by sport if none specified

#### **E. Constants**

**Filters: `/Users/stjepandzojic/projects/zos-website/app/_const/news-filters.ts`**
```typescript
export const NEWS_FILTERS = [
  { label: 'Novosti', value: 'news' },
  { label: 'Nogomet', value: 'nogomet' },
  { label: 'Odbojka', value: 'odbojka' },
  { label: 'Veslanje', value: 'veslanje' },
  // ... more sports
  { label: 'Borilački sportovi', value: 'combat-sports' },
];
```

**Configuration Type: `/Users/stjepandzojic/projects/zos-website/customtypes/news_configuration/index.json`**
- Single document (non-repeatable)
- SEO fields only: `meta_title`, `meta_description`, `meta_image` (2400x1250)

---

### **4. Navigation**

**Header Component: `/Users/stjepandzojic/projects/zos-website/app/_shared/Header.tsx`**
- Uses `RoutesList` from constants
- Desktop nav with hover effects
- Mobile hamburger menu with `<MobileMenu />`
- Integrated search with `<HeaderSearch />`

**Routes Constants: `/Users/stjepandzojic/projects/zos-website/app/_const/Routes.ts`**
```typescript
export const Routes = {
  home: '/',
  news: '/vijesti',
  events: '/dogadaji',
  about: '/o-nama',
  members: '/clanice',
  contact: '/kontakt',
  info: '/informacije',
  documents: '/propisi-i-dokumenti',
  stories: '/price-osjeckih-sportasa',
};

export const RoutesList = [
  { name: 'Vijesti', path: Routes.news },
  { name: 'Događaji', path: Routes.events },
  { name: 'Članice', path: Routes.members },
  { name: 'O nama', path: Routes.about },
];
```

---

### **5. Existing Custom Types in Prismic**

Located in `/Users/stjepandzojic/projects/zos-website/customtypes/`:
- `news/index.json` - News articles (repeatable)
- `news_configuration/index.json` - News page SEO (single)
- `event/index.json` - Events (repeatable)
- `events_configuration/index.json` - Events page SEO
- `club/index.json` - Club/Member info
- `stories/index.json` - Stories of sports people
- `stories_configuration/index.json` - Stories page SEO
- `about_us_configuration/index.json` - About page SEO
- `members_configuration/index.json` - Members page SEO
- `contact_us_configuration/index.json` - Contact page SEO
- `info/index.json` - Info articles (like FAQ/guides)

---

### **Summary: Pattern to Replicate for "Projekti" Section**

To create a "Projekti" (Projects) section following the same pattern:

1. **Create Prismic Custom Type** → `/customtypes/project/index.json`
   - Copy structure from `news` or `event`
   - Include: uid, title, description, date, hero_image, content, gallery, related_articles, sports

2. **Create Configuration Type** → `/customtypes/projects_configuration/index.json`
   - Copy structure from `news_configuration`

3. **Update Routes** → `/app/_const/Routes.ts`
   - Add: `projects: '/projekti'`

4. **Create Utilities** → `/app/_shared/utils/getProjects.ts` and `/app/projekti/utils/getSingleProject.ts`
   - Mirror `getNews.ts` and `getSingleNews.ts`

5. **Create Page Files** → `/app/projekti/page.tsx` and `/app/projekti/[uid]/page.tsx`
   - Mirror the news structure

6. **Create Components** → `/app/projekti/_fragments/`
   - `MainProjects.tsx` (list view)
   - `Archive.tsx` (filtered list with pagination)
   - `SingleProject.tsx` (detail view)

7. **Update Navigation** → `/app/_shared/Header.tsx`
   - Add route to `RoutesList`

8. **Create Constants** → `/app/_const/project-filters.ts`
   - Define category filters for projects

All TypeScript types will auto-generate in `prismicio-types.d.ts` when you update the custom types in Prismic.

