}): Promise<Metadata> {
  const { uid } = await params;
  const news = await getSingleNews(uid);

  return await generateSeoData({
    seoTitle: `${news.data.meta_title || news.data.title || 'Vijesti'} | ZOS`,
    seoDescription: news.data.meta_description || news.data.opening_text || '',
    path: `/vijesti/${uid}`,
    img: news.data.meta_image?.url || news.data.hero_image?.url || null,
  });
}

export default async function Page({
  params,
}: {
  params: Promise<{ uid: string }>;
}) {
  const { uid } = await params;
  const news = await getSingleNews(uid);

  return <SingleNews news={news} />;
}

