import { SPORTS } from '@app/_const/sports';
import { Query, filter as prismicFilter } from '@prismicio/client';
import { createClient } from 'prismicio';
import { NewsDocument } from 'prismicio-types';

interface Props {
  filter?: string;
  limit?: number;
  page?: number;
}

export async function getNews({ filter, limit = 9, page = 1 }: Props) {
  try {
    let news: Query<NewsDocument<string>>;
    const client = createClient();

    if (filter === 'news' || !filter) {
      news = await client.getByType('news', {
        orderings: {
          field: 'my.news.date',
          direction: 'desc',
        },
        pageSize: limit,
        page,
      });
    } else if (filter === 'combat-sports') {
      news = await client.getByType('news', {
        orderings: {
          field: 'my.news.date',
          direction: 'desc',
        },
        filters: [
          prismicFilter.any('my.news.sports.sport', [
            'Boks',
            'Judo',
            'Ju-jitsu',
            'Karate',
            'Kickboxing',
            'Mačevanje',
          ]),
        ],
        pageSize: limit,
        page,
      });
    } else {
      news = await client.getByType('news', {
        orderings: {
          field: 'my.news.date',
          direction: 'desc',
        },
        filters: [
          prismicFilter.at(
            'my.news.sports.sport',
            SPORTS.find((sport) => sport.value === filter)?.label ?? 'Nogomet',
          ),
        ],
        pageSize: limit,
        page,
      });
    }

    return {
      news: news.results,
      totalPages: news.total_pages || 1,
    };
  } catch {
    return { news: [], totalPages: 1 };
  }
}

