import { notFound } from 'next/navigation';
import { createClient } from 'prismicio';

export const getSingleNews = async (uid: string) => {
  try {
    const client = createClient();
    const news = await client.getByUID('news', uid);
    return news;
  } catch {
    notFound();
  }
};

