import { DateField, KeyTextField } from '@prismicio/client';
import { format } from 'date-fns';
import Image from 'next/image';
import Link from 'next/link';
import { FC } from 'react';

interface Props {
  title: KeyTextField;
  uid: string;
  date?: DateField;
  image?: string | null;
  sport?: string;
}

export const ArchiveItem: FC<Props> = ({ title, date, image, uid, sport }) => {
  return (
    <Link href={`/vijesti/${uid}`} className="group relative flex flex-col">
      {sport && (
        <div className="absolute top-0 left-0 px-12 py-12 w-full h-full flex flex-col justify-between z-[2]">
          <p className="text-tiny font-medium text-white uppercase bg-[#21262899] max-w-max px-10 py-6 rounded-2xl group-hover:bg-primary group-hover:text-white transition-all duration-300 ease-out">
            {sport}
          </p>
        </div>
      )}
      <div className="overflow-hidden relative mb-12 w-full">
        <div className="w-full h-full absolute top-0 left-0 z-[1] bg-[linear-gradient(180deg,_rgba(23,24,26,0)_0%,_rgba(23,24,26,0.6)_100%)]  group-hover:opacity-0 transition-all duration-300 ease-out" />
        {image && (
          <Image
            src={image}
            alt={title ?? ''}
            width={488}
            height={240}
            className="w-full aspect-[488/240] object-cover group-hover:scale-110 transition-all duration-300 ease-out"
          />
        )}
      </div>
      <div className="flex flex-col gap-8">
        <p className="text-base font-semibold text-white line-clamp-2">
          {title}
        </p>
        {date && (
          <p className="text-tiny text-white/40">
            {format(new Date(date), 'dd/MM/yyyy')}
          </p>
        )}
      </div>
    </Link>
  );
};

