import { filter } from '@prismicio/client';
import { createClient } from 'prismicio';

interface Props {
  search?: string;
  limit?: number;
  page?: number;
}

export async function getNewsSearch({ search, limit, page }: Props) {
  const client = createClient();

  const news = await client.getByType('news', {
    filters: [filter.fulltext('document', search ?? '')],
    orderings: {
      field: 'my.news.date',
      direction: 'desc',
    },
    pageSize: limit,
    page,
  });

  return {
    news: news.results,
    totalPages: news.total_pages,
  };
}

