import clsx from 'clsx';
import { FC } from 'react';

interface Props {
  className?: string;
  imageClassName?: string;
  isMain?: boolean;
}

export const SkeletonNewsArticle: FC<Props> = ({
  className,
  isMain,
  imageClassName,
}) => {
  return (
    <div className={clsx('flex relative w-full h-auto', className)}>
      <div className="w-full h-full absolute top-0 left-0 z-[1] bg-[linear-gradient(180deg,_rgba(23,24,26,0)_0%,_rgba(23,24,26,0.6)_100%)]" />
      <div className="absolute top-12 left-12 w-[calc(100%-24px)] h-full flex flex-col justify-between z-[2]">
        {/* Sport tag skeleton */}
        <div className="w-24 h-8 bg-gray-300 rounded-2xl animate-pulse" />

        <div className="flex flex-col justify-end gap-8 pb-16">
          {/* Title skeleton */}
          <div
            className={clsx(
              'bg-gray-300 rounded animate-pulse',
              isMain ? 'h-12' : 'h-6',
            )}
          />

          {/* Description skeleton (only for main article) */}
          {isMain && <div className="h-6 bg-gray-300 rounded animate-pulse" />}

          {/* Date skeleton */}
          <div className="w-20 h-4 bg-gray-300 rounded animate-pulse" />
        </div>
      </div>

      {/* Image skeleton */}
      <div
        className={clsx(
          'w-full h-full bg-gray-300 animate-pulse',
          imageClassName,
        )}
      />
    </div>
  );
};

