              exit={{ opacity: 0, scale: 0 }}
              transition={{ duration: 0.3, ease: 'easeInOut' }}
              className="w-full h-auto md:max-w-4/5 max-h-4/5">
              <PrismicNextImage
                field={
                  gallery[activeImage].normal_image?.url
                    ? gallery[activeImage].normal_image
                    : gallery[activeImage].cropped_image
                }
                className="w-full h-full object-contain"
              />
            </motion.div>
            <div className="w-full h-100 sm:h-[116px] flex justify-center items-center gap-16 overflow-x-auto pb-16 snap-x snap-mandatory scroll-smooth">
              {gallery.map((item, index) => (
                <motion.button
                  layoutId={`gallery-item-${index}`}
                  key={index}
                  animate={{
                    opacity: activeImage === index ? 0.4 : 1,
                  }}
                  onClick={() => setActiveImage(index)}
                  className={cn('cursor-pointer snap-center shrink-0')}>
                  <PrismicNextImage
                    field={
                      item.cropped_image?.url
                        ? item.cropped_image
                        : item.normal_image
                    }
                    width={160}
                    height={100}
                    className="object-cover min-w-[120px] max-w-[120px] min-h-[75px] max-h-[75px] sm:min-w-[160px] sm:max-w-[160px] sm:min-h-[100px] sm:max-h-[100px]"
                  />
                </motion.button>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <div className="col-span-24 grid grid-cols-24">
        <h3 className="col-[2/24] md:col-[4/22] lg:col-[7/19] text-xlarge-fluid font-medium mb-24">
          Galerija
        </h3>
        <div className="flex max-md:flex-wrap gap-12 col-span-24">
          {gallery.map((item, index) => (
            <motion.button
              layoutId={`gallery-item-${index}`}
              key={index}
              onClick={() => setActiveImage(index)}
              className="max-w-[calc(50%-12px)] md:max-w-[calc(25%-8px)] w-full h-auto cursor-pointer hover:scale-103 transition-all duration-150 ease-out">
              <PrismicNextImage
                key={index}
                field={
                  item.cropped_image?.url
                    ? item.cropped_image
                    : item.normal_image
                }
                className="w-full h-auto object-contain"
              />
            </motion.button>
          ))}
        </div>
      </div>
    </>
  );
};

